  function appearance(w,capture=false){const n=w.node,g=w.gpu,base=D.material(w.hash),rows=allRows().filter(r=>ancestor(r)===n&&val(r,OWNER)[0]===n.nativeHash).reverse().sort((a,b)=>{const depth=r=>{let d=0;for(let p=byId(r.parent);p&&p!==n;p=byId(p.parent))d++;return d;};return (a.type==='atomic_element'?0:1)-(b.type==='atomic_element'?0:1)||depth(a)-depth(b);}).map(r=>({node:r,material:D.material(r.nativeHash)})),stamp=JSON.stringify([base,...rows.map(r=>[r.node.nativeHash,identity(val(r.node,MEMBERS)),r.material,eligible(r.node)])]);if(capture||w.appearanceToken!==val(n,Z)||w.appearanceStamp!==stamp||!w.palette){const colors=new Float32Array(g.n*4);for(let i=0;i<g.n;i++){const e=elements.get(g.atoms[i].z);colors.set([...(base.custom?base.color:e.color),.68*e.r],4*i);}const byId=g.byId;for(const {node:r,material:m}of rows)if(r.tags.some(t=>t.kind==='material')||!eligible(r))for(const id of membership(r)){const i=byId.get(id);if(i!==undefined){if(m.custom)colors.set(m.color,4*i);if(!eligible(r))colors[4*i+3]=0;}}if(!w.palette||w.palette.size<colors.byteLength){w.palette?.destroy();w.palette=device.createBuffer({size:Math.max(16,colors.byteLength),usage:GPUBufferUsage.STORAGE|GPUBufferUsage.COPY_DST|GPUBufferUsage.COPY_SRC});}device.queue.writeBuffer(w.palette,0,colors);w.appearanceToken=val(n,Z);w.appearanceStamp=stamp;if(capture)return colors;}return base;}
  function render(args){const n=find(args.hash);if(n?.type!=='atomic')return;const w=world(args.hash);if(!w.gpu||w.token!==val(n,P)||w.speciesToken!==val(n,Z)){if(!w.preparing)w.preparing=serial(w,()=>ensure(w)).finally(()=>{w.preparing=null;context.requestDraw();});if(!w.gpu?.displayAtoms)return;}if(computes(n)&&(n.params.Color==='Force'&&(w.gpu.preview||w.gpu.dirtyPhysics&&!isPlaying(w))||n.params.Color==='Charge'&&w.chargeSerial!==w.gpu.displaySerial&&(!isPlaying(w)||!w.chargeAt||performance.now()-w.chargeAt>200))){if(!w.preparing)w.preparing=serial(w,()=>visualState(w)).finally(()=>{w.preparing=null;context.requestDraw();});}if(!pipelines?.atoms[+args.orthographic]){prepareRenderer().then(()=>context.requestDraw()).catch(e=>{w.error=e.message;});return;}const g=w.gpu;if(!g.n||!w.mask||w.mask.size<g.n*4)return;const material=appearance(w);w.visualUniform??=device.createBuffer({size:48,usage:GPUBufferUsage.UNIFORM|GPUBufferUsage.COPY_DST});device.queue.writeBuffer(w.visualUniform,0,new Float32Array([...g.origin,n.params.Color==='Charge'?1:n.params.Color==='Force'?2:0,material.opacity,material.emission,0,0,0,0,0,0]));w.zeroCharge??=device.createBuffer({size:16,usage:GPUBufferUsage.STORAGE|GPUBufferUsage.COPY_DST});const group=device.createBindGroup({layout:pipelines.layout,entries:[args.camera,args.frame,g.displayAtoms,w.mask,w.visualUniform,w.palette,w.charge?.chargeBuffer||w.zeroCharge,g.displayBonds].map((buffer,binding)=>({binding,resource:{buffer}}))});args.pass.setBindGroup(0,group);args.pass.setPipeline(pipelines.atoms[+args.orthographic]);args.pass.draw(6,g.n);args.pass.setPipeline(pipelines.bonds[+args.orthographic]);args.pass.drawIndirect(g.displayArgs,0);}
  function cancelPlacement(){if(!addMode)return false;addMode=null;context.requestAttributes();context.requestDraw();return true;}
  window.addEventListener('frame-engine-mode',cancelPlacement);
